    char c;
    clrscr();
    cout<<"Enter infix expression: ";
    cin>>infix;
    while(infix[i]!='\0')
    {
        c=infix[i];
        if(isalnum(c))
        postfix[j++]=c;
        else if(c=='(')
        st[++top]=c;
        else if(c==')')
        {
            while(top!=-1 && st[top]!='(')
            postfix[j++]=st[top--];
            if(top!=-1) top--;
        }
        else
        {
            while(top!=-1 && priority(st[top])>=priority(c))
            postfix[j++]=st[top--];
            st[++top]=c;
        }
        i++;
    }
    while(top!=-1) postfix[j++]=st[top--];
    postfix[j]='\0';
    cout<<"Postfix expression: "<<postfix;
