struct node
{
    int data;
    node *left,*right;
};
node* create(int x)
{
    node *p=(node*)malloc(sizeof(node));
    p->data=x; p->left=p->right=NULL;
    return p;
}
node* insert(node *root,int x)
{
    if(root==NULL) return create(x);
    if(x<root->data) root->left=insert(root->left,x);
    else if(x>root->data) root->right=insert(root->right,x);
    return root;
}
node* minNode(node *root)
{
    while(root->left!=NULL) root=root->left;
    return root;
}
node* del(node *root,int x)
{
    node *p;
    if(root==NULL) return root;
    if(x<root->data) root->left=del(root->left,x);
    else if(x>root->data) root->right=del(root->right,x);
    else
    {
        if(root->left==NULL)
        {
            p=root->right; free(root); return p;
        }
        if(root->right==NULL)
        {
            p=root->left; free(root); return p;
        }
        p=minNode(root->right);
        root->data=p->data;
        root->right=del(root->right,p->data);
    }
    return root;
}
void inorder(node *root)
{
    if(root!=NULL)
    {
        inorder(root->left);
        cout<<root->data<<" ";
        inorder(root->right);
    }
}
