    for(i=0;i<n;i++) count[(a[i]/exp)%10]++;
    for(i=1;i<10;i++) count[i]+=count[i-1];
    for(i=n-1;i>=0;i--)
    {
        output[count[(a[i]/exp)%10]-1]=a[i];
        count[(a[i]/exp)%10]--;
    }
    for(i=0;i<n;i++) a[i]=output[i];
}
